function validate(input) {
  const [{ Users = [], Register = [] }] = input;
  const users = new Set(), pairs = new Set();
  for (const [id] of Users) {
    if (id === null) return 'Every user needs a user_id.';
    if (users.has(id)) return `user_id ${id} appears twice in Users.`;
    users.add(id);
  }
  for (const [contest, user] of Register) {
    if (contest === null || user === null) return 'Every registration needs a contest_id and a user_id.';
    if (!users.has(user)) return `Register names user ${user}, who is not in Users.`;
    const key = `${contest}/${user}`;
    if (pairs.has(key)) return `User ${user} registers for contest ${contest} twice.`;
    pairs.add(key);
  }
  return null;
}

