function generate(rand, size) {
  const names = ['Alice', 'Bob', 'Alex', 'Dana', 'Eve', 'Femi', 'Kai', 'Lee'];
  const small = size === 'small';
  const userCount = small ? Math.floor(rand() * 7) : 400;
  const Users = [];
  // Ids are scattered so they are not simply 1..n.
  let id = 0;
  for (let i = 0; i < userCount; i++) { id += 1 + Math.floor(rand() * 3); Users.push([id, names[Math.floor(rand() * names.length)]]); }
  const contests = small ? [207, 208, 209, 210, 215] : Array.from({ length: 40 }, (_, i) => 100 + i * 3);
  const Register = [];
  if (Users.length) {
    for (const contest of contests) {
      // Each contest gets its own sign-up rate, so some contests share a percentage and some are full.
      const rate = small ? [0, 0.3, 0.5, 1][Math.floor(rand() * 4)] : rand() * 0.12;
      for (const [user] of Users) if (rand() < rate) Register.push([contest, user]);
    }
    for (let i = Register.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [Register[i], Register[j]] = [Register[j], Register[i]]; }
  }
  return [{ Users, Register: Register.slice(0, small ? 8 : 2000) }];
}
